mat=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
g=[[0]*30 for _ in range(30)]
for i in range(5):
 for j in range(5):
  y,x=1+7*i,1+7*j
  for dy in range(5):
   for dx in range(5):
    if y+dy<30 and x+dx<30:
     if dy in (0,4) or dx in (0,4): g[y+dy][x+dx]=4
     elif i<4 and j<4: g[y+dy][x+dx]=mat[i][j]
# Colors occurring four times among full tile centers are connectors.
from collections import Counter
cnt=Counter(v for row in mat for v in row)
target={v for v,n in cnt.items() if n==4}
# horizontal connectors between the two occurrences in each tile row
for i,row in enumerate(mat):
 for color in target:
  js=[j for j,v in enumerate(row) if v==color]
  if len(js)==2:
   for j in range(js[0],js[1]):
    for dy in range(1,4):
     for dx in (5,6): g[1+7*i+dy][1+7*j+5+dx-5]=color
# vertical connectors
for j in range(4):
 col=[mat[i][j] for i in range(4)]
 for color in target:
  ii=[i for i,v in enumerate(col) if v==color]
  if len(ii)==2:
   for i in range(ii[0],ii[1]):
    for di in (5,6):
     for dx in range(1,4):
      g[1+7*i+5+di-5][1+7*j+dx]=color
# correct bridge positions are rows tile_start+1..3 and gap columns tile_start+5,+6; vertical gap rows tile_start+5,+6
print(target)
print('\n'.join(' '.join(map(str,row)) for row in g))
